<template><div class="admin-applications-page"><AdminApplicationsTabs active="inductions" :admin="identity.role==='admin'"/><DemoIdentitySwitcher/><div v-if="identity.role!=='admin'" class="applications-queue applications-state"><strong>Admin demo view required</strong></div><div v-else-if="!induction" class="applications-queue applications-state"><strong>Induction not found</strong></div><template v-else><header class="applications-page-header"><div><RouterLink class="application-back-link" :to="{name:'AdminInductions'}">← Induction schedule</RouterLink><h1>{{induction.applicantName}}</h1><p>{{induction.applicationReference}} · {{induction.pathway}}</p><RouterLink v-if="induction.applicationId" :to="{name:'AdminApplicationDetail',params:{applicationId:induction.applicationId}}">Open related application</RouterLink><small v-else>Related application is not included in this isolated booking fixture.</small></div><span class="demo-data-badge">{{induction.status}}</span></header><div class="application-detail-grid"><main class="application-panel"><h2>Booking and meeting</h2><dl class="metadata-list"><div><dt>Acceptance origin</dt><dd>{{induction.acceptanceOrigin}}</dd></div><div><dt>Date</dt><dd>{{induction.date}}</dd></div><div><dt>Time</dt><dd>{{induction.startTime}}–{{induction.endTime}} {{induction.timeZone}}</dd></div><div><dt>Assigned staff</dt><dd>{{induction.assignedStaff}}</dd></div><div><dt>Admin attendees</dt><dd>{{induction.adminAttendees.join(', ')||'None'}}</dd></div><div><dt>Meeting state</dt><dd>{{induction.meetingState}}</dd></div><div><dt>Internal notes</dt><dd>{{induction.internalNotes}}</dd></div></dl><div class="admin-demo-controls"><button type="button" @click="attend">Mark as attending</button><button type="button" @click="join">Simulate joining meeting</button><select :value="induction.assignedStaff" aria-label="Reassign staff" @change="reassign($event.target.value)"><option v-for="s in staffOptions" :key="s">{{s}}</option></select><button type="button" @click="pendingStatus='paused'">Pause</button><button type="button" class="danger-muted" @click="pendingStatus='cancelled'">Cancel induction</button><button type="button" @click="pendingStatus='completed'">Mark completed</button></div><p class="panel-note">No meeting URL is created or opened. Provider and notification integrations remain future server boundaries.</p></main><aside class="application-panel audit-timeline"><h2>Audit history</h2><ol><li v-for="e in [...induction.auditEvents].reverse()" :key="e.id"><strong>{{e.action}}</strong><span>{{e.actor}} · {{formatTimestamp(e.timestamp)}}</span><p>{{e.summary}}</p></li></ol></aside></div><DemoActionModal v-if="pendingStatus" :title="`Mark induction ${pendingStatus}`" :warning="'This is a frontend-only audited status change.'" field-label="Internal reason" confirm-label="Confirm change" @cancel="pendingStatus=''" @confirm="changeStatus"/></template></div></template>
<script>import AdminApplicationsTabs from './components/AdminApplicationsTabs.vue';import DemoIdentitySwitcher from './components/DemoIdentitySwitcher.vue';import DemoActionModal from './components/DemoActionModal.vue';import{DEMO_STAFF,demoWorkflow,getDemoIdentity,getDemoInduction,joinDemoInduction,markAdminAttending,reassignDemoInduction,setDemoInductionStatus}from'./applicationAdminData.js';export default{name:'AdminInductionDetail',components:{AdminApplicationsTabs,DemoIdentitySwitcher,DemoActionModal},props:{inductionId:{type:String,required:true}},data:()=>({workflow:demoWorkflow,staffOptions:DEMO_STAFF,pendingStatus:''}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},induction(){this.workflow.revision;try{return this.identity.role==='admin'?getDemoInduction(this.inductionId):null}catch{return null}}},methods:{attend(){markAdminAttending(this.inductionId)},join(){joinDemoInduction(this.inductionId)},reassign(s){reassignDemoInduction(this.inductionId,s)},changeStatus(reason){setDemoInductionStatus(this.inductionId,this.pendingStatus,reason);this.pendingStatus=''},formatTimestamp(v){return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}}};</script><style src="./AdminApplications.css"></style>
